        "Pizzatészta: az élesztőt 3 dl langyos vízben a cukorral elkevered, és 5–10 percig állni hagyod, amíg habos lesz. Egy tálban a lisztet a sóval összekevered, hozzáöntöd az élesztős vizet és az olívaolajat, és 8–10 percig sima, rugalmas, kissé ragadós tésztává dagasztod. Kiolajozott tálban, letakarva, meleg helyen 1 órát keleszted, amíg duplájára nő.",
